CREATE TRIGGER material_generation_input_project BEFORE INSERT ON material_evidence_inputs WHEN NEW.request_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM material_generation_requests r WHERE r.id=NEW.request_id AND ((NEW.document_version_id IS NOT NULL AND EXISTS(SELECT 1 FROM study_document_versions v JOIN study_documents d ON d.id=v.document_id JOIN project_documents p ON p.document_id=d.id WHERE v.id=NEW.document_version_id AND v.status='published' AND d.archived_at IS NULL AND p.project_id=r.project_id AND NOT EXISTS(SELECT 1 FROM study_document_retirements x WHERE x.version_id=v.id))) OR (NEW.source_id IS NOT NULL AND EXISTS(SELECT 1 FROM sources s JOIN source_extraction_revisions e ON e.source_id=s.id WHERE s.id=NEW.source_id AND s.project_id=r.project_id AND e.revision=NEW.source_revision AND e.snapshot_id=NEW.source_snapshot_id)))) BEGIN SELECT RAISE(ABORT,'exact learning input is outside its project'); END;
--> statement-breakpoint
CREATE TRIGGER material_generation_publication_input_project BEFORE UPDATE OF status ON material_versions
WHEN NEW.status='published' AND OLD.status!='published' AND NEW.generation_request_id IS NOT NULL AND EXISTS(SELECT 1 FROM material_generation_requests r JOIN material_evidence_inputs i ON i.request_id=r.id WHERE r.id=NEW.generation_request_id AND NOT ((i.document_version_id IS NOT NULL AND EXISTS(SELECT 1 FROM study_document_versions v JOIN study_documents d ON d.id=v.document_id JOIN project_documents p ON p.document_id=d.id WHERE v.id=i.document_version_id AND v.status='published' AND d.archived_at IS NULL AND p.project_id=r.project_id AND NOT EXISTS(SELECT 1 FROM study_document_retirements x WHERE x.version_id=v.id))) OR (i.source_id IS NOT NULL AND EXISTS(SELECT 1 FROM sources s JOIN source_extraction_revisions e ON e.source_id=s.id WHERE s.id=i.source_id AND s.project_id=r.project_id AND e.revision=i.source_revision AND e.snapshot_id=i.source_snapshot_id))))
BEGIN SELECT RAISE(ABORT,'exact learning input is outside its project'); END;
--> statement-breakpoint
CREATE TRIGGER material_generation_receipt_input_project BEFORE UPDATE OF result_version_id ON material_generation_requests
WHEN OLD.result_version_id IS NULL AND NEW.result_version_id IS NOT NULL AND EXISTS(SELECT 1 FROM material_generation_requests r JOIN material_evidence_inputs i ON i.request_id=r.id WHERE r.id=NEW.id AND NOT ((i.document_version_id IS NOT NULL AND EXISTS(SELECT 1 FROM study_document_versions v JOIN study_documents d ON d.id=v.document_id JOIN project_documents p ON p.document_id=d.id WHERE v.id=i.document_version_id AND v.status='published' AND d.archived_at IS NULL AND p.project_id=r.project_id AND NOT EXISTS(SELECT 1 FROM study_document_retirements x WHERE x.version_id=v.id))) OR (i.source_id IS NOT NULL AND EXISTS(SELECT 1 FROM sources s JOIN source_extraction_revisions e ON e.source_id=s.id WHERE s.id=i.source_id AND s.project_id=r.project_id AND e.revision=i.source_revision AND e.snapshot_id=i.source_snapshot_id))))
BEGIN SELECT RAISE(ABORT,'exact learning input is outside its project'); END;
